    final resume = sid != null && _resumeSentFor != sid;
    final argv = reportStateArgs(
      state: state,
      label: label,
      seq: _nextSeq(),
      sessionId: sid,
      includeResumeArgv: resume,
    );
    if (resume) _resumeSentFor = sid;
    _spawn(argv);
  }

