      final release = reports.singleWhere(
        (argv) => _op(argv) == 'release-agent',
      );
      expect(release, isNot(contains(bootId)));
      expect(reports.where((argv) => argv.contains('--agent-session-id')), [
        reports.first,
        resetReport,
      ]);
    },
  );

