          'HERDR_PANE_ID': 'w6:p16',
          'HERDR_BIN_PATH': '/u/b/h',
        },
        'pane missing': {'HERDR_ENV': '1', 'HERDR_BIN_PATH': '/u/b/h'},
        'pane invalid charset': {
          'HERDR_ENV': '1',
          'HERDR_PANE_ID': 'w6 p16',
          'HERDR_BIN_PATH': '/u/b/h',
        },
        'pane path-shaped': {
          'HERDR_ENV': '1',
          'HERDR_PANE_ID': 'a/b',
          'HERDR_BIN_PATH': '/u/b/h',
        },
        'bin missing': {'HERDR_ENV': '1', 'HERDR_PANE_ID': 'w6:p16'},
        'bin relative': {
