    Map<String, String> env, {
    DateTime Function()? clock,
    Duration timeout = const Duration(seconds: 2),
  }) {
    final sink = <List<String>>[];
    final reporter = HerdrReporter(
      envLookup: (name) => env[name],
      runProcess: (argv) async {
        sink.add(argv);
      },
      clock: clock,
      timeout: timeout,
