    test('release report', () async {
      final (reporter, sink) = wired(
        herdrEnv(),
        clock: () => DateTime.fromMillisecondsSinceEpoch(5000),
      );
      await _release(reporter);
      const expected = <List<String>>[
        [
          '/opt/homebrew/bin/herdr',
          'pane',
          'release-agent',
          'w6:p16',
          '--source',
          'fa',
