            '173000_ab12',
            '--seq',
            '7000',
            '--',
            'fa',
            '--session',
            '173000_ab12',
          ],
        ];
        expect(sink, expected);
        expect(sink.where((argv) => argv.contains('release-agent')), isEmpty);
      },
    );

    test('labelFor maps the sealed prompt specs onto the four labels', () {
      expect(
        HerdrReporter.labelFor(
          ApprovalPromptSpec(
