    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: '[REDACTED:Sensitive Value]',
        env: env,
        sessionRoot: '/sessions',
        herdrEnvLookup: (name) => pane[name],
        herdrSpawn: (argv) async {
          reports.add(argv);
