    String pane = 'w6:p16',
    String bin = '/opt/homebrew/bin/herdr',
    String? kill,
  }) {
    return {
      'HERDR_ENV': env,
      'HERDR_PANE_ID': pane,
      'HERDR_BIN_PATH': bin,
      'FA_HERDR': ?kill,
