  /// A fully-populated herdr pane environment (the incident session's
  /// shape: herdr 0.8.2, pane `w6:p16`).
  Map<String, String> herdrEnv({
    String env = '1',
    String pane = 'w6:p16',
    String bin = '/opt/homebrew/bin/herdr',
    String? kill,
  }) {
    return {
      'HERDR_ENV': env,
      'HERDR_PANE_ID': pane,
      'HERDR_BIN_PATH': bin,
      'FA_HERDR': ?kill,
    };
  }

