// bin/fah_herdr_spawn.dart
/// The herdr report spawn transport (issue #1483 review): ...
library;

import 'dart:async';
import 'dart:io';

/// Spawns one herdr `pane …` report fire-and-forget: kill-on-timeout (5s)
/// with drained stdio so a chatty herdr can never block on a full pipe.
Future<void> spawnHerdrReport(List<String> argv) async {
  final process = await Process.start(argv.first, argv.sublist(1));
  unawaited(process.stdout.drain<void>());
  unawaited(process.stderr.drain<void>());
  await process.exitCode.timeout(
    const Duration(seconds: 5),
    onTimeout: () {
      process.kill();
      return process.exitCode;
    },
  );
}
```

