/// Spawns one herdr `pane …` report fire-and-forget: kill-on-timeout (5s)
/// with drained stdio so a chatty herdr can never block on a full pipe.
Future<void> spawnHerdrReport(List<String> argv) async {
  final process = await Process.start(argv.first, argv.sublist(1));
